import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  PieChart,
  Pie,
  Cell,
  Legend,
} from "recharts";
import Header from "./../../components/Header/Header";
import Footer from "./../../components/Footer/Footer";
import "./../completion-page/completionpage.css";

interface Evaluation {
  question: string;
  difficulty: string;
  subject: string;
  subtopic: string;
  reference_answer: string;
  user_answer: string;
  explanation: string;
  grammar_score: number;
  cosine_similarity_score: number;
  keyword_score: number;
  llm_relevance_score: number;
  total_score: number;
}

const CompletionPage: React.FC = () => {
  const [evaluations, setEvaluations] = useState<Evaluation[]>([]);
  const [finalScore, setFinalScore] = useState<number>(0);
  const [message, setMessage] = useState<string>("");
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const { testid: paramTestId } = useParams();

  useEffect(() => {
    const fetchCompletionData = async () => {
      const storedTestId = localStorage.getItem("test_id");
      const testid = paramTestId || storedTestId;

      if (!testid) {
        setError("Test ID not found. Please try again.");
        setLoading(false);
        return;
      }

      try {
        const response = await fetch("http://localhost:5000/view_result", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ testid }),
        });
        const data = await response.json();

        if (response.ok) {
          setEvaluations(data.evaluations);
          setFinalScore(data.final_score);
          setMessage(data.message);
        } else {
          setError(data.error || "Failed to load the completion data.");
        }
      } catch (err) {
        console.error("Error fetching completion data:", err);
        setError("Failed to load the completion data.");
      } finally {
        setLoading(false);
      }
    };

    fetchCompletionData();
  }, [paramTestId]);

  if (loading) {
    return (
      <div className="App">
        <Header />
        <div className="main-content">
          <h2>Loading...</h2>
        </div>
        <Footer />
      </div>
    );
  }

  if (error) {
    return (
      <div className="App">
        <Header />
        <div className="main-content">
          <h2>{error}</h2>
        </div>
        <Footer />
      </div>
    );
  }

  // Data processing for charts
  const subjectScores = evaluations.reduce<{ [key: string]: number }>(
    (acc, curr) => {
      acc[curr.subject] = (acc[curr.subject] || 0) + curr.total_score;
      return acc;
    },
    {}
  );

  const barChartData = Object.entries(subjectScores).map(
    ([subject, total_score]) => ({ subject, total_score })
  );

  const difficultyCounts = evaluations.reduce<{ [key: string]: number }>(
    (acc, curr) => {
      acc[curr.difficulty] = (acc[curr.difficulty] || 0) + 1;
      return acc;
    },
    {}
  );

  const pieChartData = Object.entries(difficultyCounts).map(
    ([difficulty, count]) => ({ name: difficulty, value: count })
  );

  const COLORS = ["#0088FE", "#00C49F", "#FFBB28"];

  return (
    <div className="App">
      <Header />
      <div className="main-content">
        <h3>{message}</h3>
        <h5>Overall Score: {finalScore}</h5>
        <div className="evaluations">
          {evaluations.map((evaluation, index) => (
            <div key={index} className="evaluation">
              <div>
                <span className="subject">{evaluation.subject}</span>
                <span className="subtopic">{evaluation.subtopic}</span>
                <span className="difficulty" style={{ backgroundColor: evaluation.difficulty === "Easy" ? "green" : evaluation.difficulty === "Hard" ? "red" : "yellow" }}>{evaluation.difficulty}</span>
              </div>
              <h4>Question {index + 1}: {evaluation.question}</h4>
              <p><strong>Reference Answer:</strong> {evaluation.reference_answer}</p>
              <p><strong>Your Answer:</strong> {evaluation.user_answer}</p>
              <p><strong>Explanation:</strong> {evaluation.explanation}</p>
              <div className="scores">
                <p><strong>Grammar Score:</strong> {evaluation.grammar_score}</p>
                <p><strong>Cosine Similarity Score:</strong> {evaluation.cosine_similarity_score}</p>
                <p><strong>Keyword Score:</strong> {evaluation.keyword_score}</p>
                <p><strong>LLM Relevance Score:</strong> {evaluation.llm_relevance_score}</p>
              </div>
              <p><strong>Total Score for this Question:</strong> {evaluation.total_score}</p>
              <hr />
            </div>
          ))}
        </div>

        <div className="charts">
          <h2>Performance Visualization</h2>
          <BarChart width={500} height={300} data={barChartData}>
            <XAxis dataKey="subject" />
            <YAxis />
            <Tooltip />
            <Bar dataKey="total_score" fill="#8884d8" />
          </BarChart>

          <PieChart width={400} height={400}>
            <Pie data={pieChartData} cx="50%" cy="50%" outerRadius={100} fill="#8884d8" dataKey="value">
              {pieChartData.map((_, index) => (
                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
              ))}
            </Pie>
            <Tooltip />
            <Legend />
          </PieChart>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default CompletionPage;
